import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Solid","description":"Solid reference documentation","frontmatter":{"title":"Solid","description":"Solid reference documentation"},"headers":[],"relativePath":"knowledge/solid.md","filePath":"knowledge/solid.md","lastUpdated":1784485118000}'),s={name:"knowledge/solid.md"};function a(r,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="solid" tabindex="-1">Solid <a class="header-anchor" href="#solid" aria-label="Permalink to &quot;Solid&quot;">​</a></h1><h1 id="solid-principles-—-knowledge-base" tabindex="-1">SOLID Principles — Knowledge Base <a class="header-anchor" href="#solid-principles-—-knowledge-base" aria-label="Permalink to &quot;SOLID Principles — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>SOLID is a mnemonic acronym for five object-oriented design principles that make software more understandable, flexible, and maintainable. This knowledge base provides practical TypeScript/React examples for each principle and common violations to avoid.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="single-responsibility-principle-srp" tabindex="-1">Single Responsibility Principle (SRP) <a class="header-anchor" href="#single-responsibility-principle-srp" aria-label="Permalink to &quot;Single Responsibility Principle (SRP)&quot;">​</a></h3><p>A module should have one, and only one, reason to change. Each class, function, or module should encapsulate a single piece of functionality.</p><p><strong>Why it matters:</strong> Changes to one concern don&#39;t ripple into unrelated code. Testing is focused. Code is easier to understand.</p><h3 id="open-closed-principle-ocp" tabindex="-1">Open/Closed Principle (OCP) <a class="header-anchor" href="#open-closed-principle-ocp" aria-label="Permalink to &quot;Open/Closed Principle (OCP)&quot;">​</a></h3><p>Software entities should be open for extension but closed for modification. You should be able to add new behavior without changing existing code.</p><p><strong>Why it matters:</strong> Adding new features doesn&#39;t risk breaking existing functionality. Existing tests remain valid.</p><h3 id="liskov-substitution-principle-lsp" tabindex="-1">Liskov Substitution Principle (LSP) <a class="header-anchor" href="#liskov-substitution-principle-lsp" aria-label="Permalink to &quot;Liskov Substitution Principle (LSP)&quot;">​</a></h3><p>Objects of a supertype should be replaceable with objects of a subtype without altering the correctness of the program. Subtypes must be substitutable for their base types.</p><p><strong>Why it matters:</strong> Polymorphism works correctly. Code that uses a base type works identically with any derived type.</p><h3 id="interface-segregation-principle-isp" tabindex="-1">Interface Segregation Principle (ISP) <a class="header-anchor" href="#interface-segregation-principle-isp" aria-label="Permalink to &quot;Interface Segregation Principle (ISP)&quot;">​</a></h3><p>Clients should not be forced to depend on interfaces they don&#39;t use. Prefer small, specific interfaces over large, general-purpose ones.</p><p><strong>Why it matters:</strong> Reduces unnecessary coupling. Changes to unused methods don&#39;t affect clients. Easier to mock for testing.</p><h3 id="dependency-inversion-principle-dip" tabindex="-1">Dependency Inversion Principle (DIP) <a class="header-anchor" href="#dependency-inversion-principle-dip" aria-label="Permalink to &quot;Dependency Inversion Principle (DIP)&quot;">​</a></h3><p>High-level modules should not depend on low-level modules. Both should depend on abstractions (interfaces). Abstractions should not depend on details; details should depend on abstractions.</p><p><strong>Why it matters:</strong> Business logic is independent of infrastructure. Swapping implementations (Supabase → Prisma) requires changing only adapter code.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Apply SRP at the function level</strong> — Each function should do one thing; if a function does input validation AND database insertion, split it</li><li><strong>Use TypeScript interfaces for extension points</strong> — Define interfaces at module boundaries; new implementations can extend without modifying existing code</li><li><strong>Verify LSP with behavioral tests</strong> — Write tests that operate on base types and pass derived types; any failure indicates LSP violation</li><li><strong>Prefer multiple small interfaces over one large</strong> — Split <code>UserRepository</code> into <code>UserReader</code> and <code>UserWriter</code> if clients need different operations</li><li><strong>Inject dependencies through constructors</strong> — Pass dependencies as constructor parameters; never instantiate concrete classes inside business logic</li><li><strong>Use composition over inheritance</strong> — Compose behaviors with small modules rather than creating deep inheritance trees</li><li><strong>Extract strategies for varying behavior</strong> — When behavior varies, use the Strategy pattern (interface + implementations) rather than conditionals</li><li><strong>Refactor toward SOLID incrementally</strong> — Don&#39;t rewrite existing code; refactor toward principles one function at a time during feature work</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>God class</strong> — A single class handling user management, email sending, and payment processing violates SRP; split into focused modules</li><li><strong>Switch statements for type dispatch</strong> — Large switch/case blocks that add new branches for each type violate OCP; use polymorphism instead</li><li><strong>Type narrowing with <code>as</code> casts</strong> — Using type assertions to force compatibility violates LSP; redesign the type hierarchy instead</li><li><strong>Fat interfaces with unused methods</strong> — An interface with 20 methods where clients use 2 violates ISP; split into focused interfaces</li><li><strong>Instantiating dependencies inside business logic</strong> — <code>const repo = new SupabaseRepo()</code> inside a use case violates DIP; inject the dependency</li><li><strong>Deep inheritance hierarchies</strong> — <code>BaseService → CrudService → UserService → AdminUserService</code> is fragile; use composition instead</li><li><strong>Return type violations</strong> — A subtype returning a more restrictive type than the parent violates LSP; return types must be covariant or identical</li><li><strong>Framework dependencies in domain code</strong> — Importing <code>next/navigation</code> in entity classes couples business logic to Next.js; use abstractions</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Applying all five principles simultaneously</strong> — Over-application leads to over-engineering; apply proportionally to the complexity of each module</li><li><strong>Confusing SRP with &quot;one method per class&quot;</strong> — SRP means one reason to change, not extreme decomposition; cohesive related methods are fine</li><li><strong>Creating interfaces for everything</strong> — Not every class needs an interface; add abstractions only when you have multiple implementations or need testability</li><li><strong>Using inheritance when composition suffices</strong> — <code>class AdminUser extends User</code> seems natural but <code>class User { role: Role }</code> is more flexible</li><li><strong>Ignoring principle interactions</strong> — SRP and DIP work together; well-separated responsibilities make dependency inversion natural</li><li><strong>Over-abstracting simple modules</strong> — A utility function that formats dates doesn&#39;t need an interface and implementation; keep it simple</li><li><strong>Applying OCP to every conditional</strong> — Not every <code>if</code> statement needs the Strategy pattern; OCP applies to stable interfaces with changing implementations</li><li><strong>Forgetting that SOLID applies to modules, not just classes</strong> — File-level module organization should follow SOLID; one module per concern</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Primary Principle</th><th>Application</th></tr></thead><tbody><tr><td>Feature has multiple reasons to change</td><td>SRP</td><td>Split into separate modules per concern</td></tr><tr><td>New variants of a behavior expected</td><td>OCP</td><td>Define interface; new variants implement without modifying</td></tr><tr><td>Polymorphic code has bugs</td><td>LSP</td><td>Review subtype contracts; ensure substitutability</td></tr><tr><td>Module changes ripple across codebase</td><td>ISP + DIP</td><td>Narrow interfaces; inject dependencies</td></tr><tr><td>Testing requires extensive mocking</td><td>ISP + DIP</td><td>Smaller interfaces; dependency injection</td></tr><tr><td>Refactoring legacy code</td><td>All (incremental)</td><td>Extract methods → extract classes → introduce interfaces</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>&quot;Clean Architecture&quot; by Robert C. Martin</li><li>&quot;Agile Software Development: Principles, Patterns, and Practices&quot; by Robert C. Martin</li><li>TypeScript Handbook: <a href="https://www.typescriptlang.org/docs/handbook/" target="_blank" rel="noreferrer">https://www.typescriptlang.org/docs/handbook/</a></li><li>Refactoring Guru — SOLID: <a href="https://refactoring.guru/design-patterns/solid" target="_blank" rel="noreferrer">https://refactoring.guru/design-patterns/solid</a></li><li>Martin Fowler&#39;s blog: <a href="https://martinfowler.com/" target="_blank" rel="noreferrer">https://martinfowler.com/</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>TypeScript advantages:</strong> TypeScript&#39;s type system makes SOLID violations visible at compile time; leverage interfaces and generics</li><li><strong>React hooks:</strong> Custom hooks naturally support DIP by abstracting state logic; components depend on hook interfaces, not implementations</li><li><strong>Next.js patterns:</strong> Route Handlers are presentation layer; extract business logic into use cases; use Supabase through repository interfaces</li><li><strong>Testing impact:</strong> SOLID code is dramatically easier to test; if testing requires elaborate setup, the code likely violates a principle</li><li><strong>Team adoption:</strong> Introduce SOLID through code review; point out violations and refactor together rather than mandating upfront</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',34)])])}const g=t(s,[["render",a]]);export{u as __pageData,g as default};
